package ndr

import (
	"encoding/hex"
	"testing"
)

// capturedReadResp mirrors the EfsRpcReadFileRaw reply: the [out] EFS_EXIM_PIPE (a pipe
// of bytes) followed by the NTSTATUS return value.
type capturedReadResp struct {
	Pipe   []byte `ndr:"pipe"`
	Status uint32 `ndr:"retval"`
}

// ndr64ReadFileRawStub is the raw [out] stub of a real EfsRpcReadFileRaw response captured
// over NDR64 from Windows Server 2016 (.private/capture_pipe.go). Its pipe chunks are
// [+count(8)][bytes][-count(8)] with a 0(8) terminator; decoding yields a 2300-octet EFS
// raw-export payload.
const ndr64ReadFileRawStub = ""

// TestNDR64_PipeFromCapture decodes the captured NDR64 EFS pipe and round-trips its
// payload, anchoring the NDR64 pipe decoder to real Windows wire bytes.
func TestNDR64_PipeFromCapture(t *testing.T) {
	stub, err := hex.DecodeString(ndr64ReadFileRawStub)
	if err != nil {
		t.Fatalf("decode hex: %v", err)
	}
	var resp capturedReadResp
	if err := UnmarshalAs(stub, &resp, NDR64); err != nil {
		t.Fatalf("UnmarshalAs NDR64: %v", err)
	}
	if len(resp.Pipe) != 2300 {
		t.Fatalf("pipe payload = %d octets, want 2300", len(resp.Pipe))
	}
	if resp.Status != 0 {
		t.Errorf("status = %#x, want 0 (success)", resp.Status)
	}

	// Round-trip the recovered payload as a single-chunk NDR64 pipe.
	wire, err := MarshalAs(&capturedReadResp{Pipe: resp.Pipe}, NDR64)
	if err != nil {
		t.Fatalf("MarshalAs NDR64: %v", err)
	}
	var back capturedReadResp
	if err := UnmarshalAs(wire, &back, NDR64); err != nil {
		t.Fatalf("re-unmarshal: %v", err)
	}
	if len(back.Pipe) != 2300 || string(back.Pipe) != string(resp.Pipe) {
		t.Errorf("pipe round trip mismatch (%d octets)", len(back.Pipe))
	}
}
